composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      POSTGRES_HOST: "{{serviceName}}-postgres"
      POSTGRES_DB: khoj
      POSTGRES_USER: khoj
      KHOJ_DJANGO_SECRET_KEY: {{env.KHOJ_DJANGO_SECRET_KEY}}
      KHOJ_ADMIN_EMAIL: {{env.KHOJ_ADMIN_EMAIL}}
      KHOJ_ADMIN_PASSWORD: {{env.KHOJ_ADMIN_PASSWORD}}
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
    volumes:
      - {{appDataPath}}/config:/root/.khoj
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: pgvector/pgvector:pg15
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: khoj
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      POSTGRES_DB: khoj
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
